TemplateBody:
{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description": "One shared finite-task slot and a 120 two-vCPU-task-minute/day reservation limit for Live renderer and optional transcription. No always-on ECS compute.",
  "Parameters": {
    "RendererClusterArn": {
      "Type": "String",
      "AllowedPattern": "(?:arn:aws:ecs:us-east-2:[0-9]{12}:cluster/[A-Za-z0-9_-]+)"
    },
    "RendererTaskDefinitionArn": {
      "Type": "String",
      "AllowedPattern": "(?:arn:aws:ecs:us-east-2:[0-9]{12}:task-definition/[A-Za-z0-9_-]+:[1-9][0-9]*)"
    },
    "RendererExecutionRoleArn": {
      "Type": "String",
      "AllowedPattern": "arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+"
    },
    "RendererSecurityGroupId": {
      "Type": "AWS::EC2::SecurityGroup::Id"
    },
    "RendererSubnetIds": {
      "Type": "List<AWS::EC2::Subnet::Id>"
    },
    "QueueKeyArn": {
      "Type": "String",
      "AllowedPattern": "(?:arn:aws:kms:us-east-2:[0-9]{12}:key/[a-f0-9-]{36})"
    },
    "SupabaseProjectRef": {
      "Type": "String",
      "Default": "prlkikhckbifseosbukl",
      "AllowedPattern": "[a-z0-9]{20}"
    },
    "ScheduleEnabled": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": [
        "false",
        "true"
      ],
      "Description": "Enable only after queue-only credentials match and controlled launcher acceptance passes."
    },
    "AsrEnabled": {
      "Type": "String",
      "Default": "false",
      "AllowedValues": [
        "false",
        "true"
      ]
    },
    "AsrClusterArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:ecs:us-east-2:[0-9]{12}:cluster/[A-Za-z0-9_-]+)"
    },
    "AsrTaskDefinitionArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:ecs:us-east-2:[0-9]{12}:task-definition/[A-Za-z0-9_-]+:[1-9][0-9]*)"
    },
    "AsrExecutionRoleArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+)"
    },
    "AsrTaskRoleArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9_+=,.@/-]+)"
    },
    "AsrSecurityGroupId": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|sg-[a-f0-9]{8,17})"
    },
    "AsrSubnetIds": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|subnet-[a-f0-9]{8,17}(?:,subnet-[a-f0-9]{8,17}){0,2})"
    },
    "AsrQueueSecretArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:secretsmanager:us-east-2:[0-9]{12}:secret:[A-Za-z0-9/_+=.@-]+)"
    },
    "AsrQueueKeyArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:kms:us-east-2:[0-9]{12}:key/[a-f0-9-]{36})"
    },
    "AlarmTopicArn": {
      "Type": "String",
      "Default": "",
      "AllowedPattern": "(?:|arn:aws:sns:us-east-2:[0-9]{12}:[A-Za-z0-9_-]+)"
    }
  },
  "Rules": {
    "CompleteAsrConfiguration": {
      "RuleCondition": {
        "Fn::Equals": [
          {
            "Ref": "AsrEnabled"
          },
          "true"
        ]
      },
      "Assertions": [
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrClusterArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrClusterArn must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrTaskDefinitionArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrTaskDefinitionArn must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrExecutionRoleArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrExecutionRoleArn must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrTaskRoleArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrTaskRoleArn must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrSecurityGroupId"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrSecurityGroupId must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrSubnetIds"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrSubnetIds must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrQueueSecretArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrQueueSecretArn must be supplied when ASR scheduling is enabled."
        },
        {
          "Assert": {
            "Fn::Not": [
              {
                "Fn::Equals": [
                  {
                    "Ref": "AsrQueueKeyArn"
                  },
                  ""
                ]
              }
            ]
          },
          "AssertDescription": "AsrQueueKeyArn must be supplied when ASR scheduling is enabled."
        }
      ]
    }
  },
  "Conditions": {
    "Enabled": {
      "Fn::Equals": [
        {
          "Ref": "ScheduleEnabled"
        },
        "true"
      ]
    },
    "HasAsr": {
      "Fn::And": [
        {
          "Fn::Equals": [
            {
              "Ref": "AsrEnabled"
            },
            "true"
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrClusterArn"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrTaskDefinitionArn"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrExecutionRoleArn"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrTaskRoleArn"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrSecurityGroupId"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrSubnetIds"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrQueueSecretArn"
                },
                ""
              ]
            }
          ]
        },
        {
          "Fn::Not": [
            {
              "Fn::Equals": [
                {
                  "Ref": "AsrQueueKeyArn"
                },
                ""
              ]
            }
          ]
        }
      ]
    },
    "HasAlarmTopic": {
      "Fn::Not": [
        {
          "Fn::Equals": [
            {
              "Ref": "AlarmTopicArn"
            },
            ""
          ]
        }
      ]
    }
  },
  "Resources": {
    "QueueSecret": {
      "Type": "AWS::SecretsManager::Secret",
      "DeletionPolicy": "Retain",
      "UpdateReplacePolicy": "Retain",
      "Properties": {
        "Description": "Queue metadata only. Install the matching value as LIVE_CLIP_QUEUE_SECRET; it cannot claim, sign or finish clip jobs.",
        "KmsKeyId": {
          "Ref": "QueueKeyArn"
        },
        "GenerateSecretString": {
          "PasswordLength": 64,
          "ExcludePunctuation": true,
          "IncludeSpace": false
        },
        "Tags": [
          {
            "Key": "Application",
            "Value": "PlatinumCircles"
          },
          {
            "Key": "Purpose",
            "Value": "LiveTaskLauncher"
          }
        ]
      }
    },
    "Ledger": {
      "Type": "AWS::DynamoDB::Table",
      "DeletionPolicy": "Retain",
      "UpdateReplacePolicy": "Retain",
      "Properties": {
        "BillingMode": "PAY_PER_REQUEST",
        "AttributeDefinitions": [
          {
            "AttributeName": "id",
            "AttributeType": "S"
          }
        ],
        "KeySchema": [
          {
            "AttributeName": "id",
            "KeyType": "HASH"
          }
        ],
        "SSESpecification": {
          "SSEEnabled": true
        },
        "PointInTimeRecoverySpecification": {
          "PointInTimeRecoveryEnabled": true
        },
        "TimeToLiveSpecification": {
          "AttributeName": "expires_at",
          "Enabled": true
        },
        "Tags": [
          {
            "Key": "Application",
            "Value": "PlatinumCircles"
          },
          {
            "Key": "Purpose",
            "Value": "LiveTaskLauncher"
          }
        ]
      }
    },
    "LauncherLogs": {
      "Type": "AWS::Logs::LogGroup",
      "DeletionPolicy": "Retain",
      "UpdateReplacePolicy": "Retain",
      "Properties": {
        "LogGroupName": {
          "Fn::Sub": "/platinum/live-clips/${AWS::StackName}/launcher"
        },
        "RetentionInDays": 14,
        "Tags": [
          {
            "Key": "Application",
            "Value": "PlatinumCircles"
          },
          {
            "Key": "Purpose",
            "Value": "LiveTaskLauncher"
          }
        ]
      }
    },
    "LauncherRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {
                "Service": "lambda.amazonaws.com"
              },
              "Action": "sts:AssumeRole"
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "BoundedLiveTaskLauncher",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Effect": "Allow",
                  "Action": [
                    "logs:CreateLogStream",
                    "logs:PutLogEvents"
                  ],
                  "Resource": {
                    "Fn::GetAtt": [
                      "LauncherLogs",
                      "Arn"
                    ]
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": [
                    "dynamodb:GetItem",
                    "dynamodb:UpdateItem",
                    "dynamodb:PutItem"
                  ],
                  "Resource": {
                    "Fn::GetAtt": [
                      "Ledger",
                      "Arn"
                    ]
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": "ecs:RunTask",
                  "Resource": {
                    "Ref": "RendererTaskDefinitionArn"
                  },
                  "Condition": {
                    "ArnEquals": {
                      "ecs:cluster": {
                        "Ref": "RendererClusterArn"
                      }
                    }
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": [
                    "ecs:DescribeTasks",
                    "ecs:StopTask"
                  ],
                  "Resource": {
                    "Fn::Join": [
                      "",
                      [
                        {
                          "Fn::Sub": "arn:${AWS::Partition}:ecs:${AWS::Region}:${AWS::AccountId}:task/"
                        },
                        {
                          "Fn::Select": [
                            1,
                            {
                              "Fn::Split": [
                                ":cluster/",
                                {
                                  "Ref": "RendererClusterArn"
                                }
                              ]
                            }
                          ]
                        },
                        "/*"
                      ]
                    ]
                  },
                  "Condition": {
                    "ArnEquals": {
                      "ecs:cluster": {
                        "Ref": "RendererClusterArn"
                      }
                    }
                  }
                },
                {
                  "Fn::If": [
                    "HasAsr",
                    {
                      "Effect": "Allow",
                      "Action": "ecs:RunTask",
                      "Resource": {
                        "Ref": "AsrTaskDefinitionArn"
                      },
                      "Condition": {
                        "ArnEquals": {
                          "ecs:cluster": {
                            "Ref": "AsrClusterArn"
                          }
                        }
                      }
                    },
                    {
                      "Ref": "AWS::NoValue"
                    }
                  ]
                },
                {
                  "Fn::If": [
                    "HasAsr",
                    {
                      "Effect": "Allow",
                      "Action": [
                        "ecs:DescribeTasks",
                        "ecs:StopTask"
                      ],
                      "Resource": {
                        "Fn::Join": [
                          "",
                          [
                            {
                              "Fn::Sub": "arn:${AWS::Partition}:ecs:${AWS::Region}:${AWS::AccountId}:task/"
                            },
                            {
                              "Fn::Select": [
                                1,
                                {
                                  "Fn::Split": [
                                    ":cluster/",
                                    {
                                      "Ref": "AsrClusterArn"
                                    }
                                  ]
                                }
                              ]
                            },
                            "/*"
                          ]
                        ]
                      },
                      "Condition": {
                        "ArnEquals": {
                          "ecs:cluster": {
                            "Ref": "AsrClusterArn"
                          }
                        }
                      }
                    },
                    {
                      "Ref": "AWS::NoValue"
                    }
                  ]
                },
                {
                  "Effect": "Allow",
                  "Action": "iam:PassRole",
                  "Resource": [
                    {
                      "Ref": "RendererExecutionRoleArn"
                    },
                    {
                      "Fn::If": [
                        "HasAsr",
                        {
                          "Ref": "AsrExecutionRoleArn"
                        },
                        {
                          "Ref": "AWS::NoValue"
                        }
                      ]
                    },
                    {
                      "Fn::If": [
                        "HasAsr",
                        {
                          "Ref": "AsrTaskRoleArn"
                        },
                        {
                          "Ref": "AWS::NoValue"
                        }
                      ]
                    }
                  ],
                  "Condition": {
                    "StringEquals": {
                      "iam:PassedToService": "ecs-tasks.amazonaws.com"
                    }
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": [
                    "secretsmanager:GetSecretValue"
                  ],
                  "Resource": [
                    {
                      "Ref": "QueueSecret"
                    },
                    {
                      "Fn::If": [
                        "HasAsr",
                        {
                          "Ref": "AsrQueueSecretArn"
                        },
                        {
                          "Ref": "AWS::NoValue"
                        }
                      ]
                    }
                  ],
                  "Condition": {
                    "Bool": {
                      "aws:SecureTransport": "true"
                    }
                  }
                },
                {
                  "Effect": "Allow",
                  "Action": "kms:Decrypt",
                  "Resource": {
                    "Ref": "QueueKeyArn"
                  },
                  "Condition": {
                    "StringEquals": {
                      "kms:ViaService": {
                        "Fn::Sub": "secretsmanager.${AWS::Region}.${AWS::URLSuffix}"
                      },
                      "kms:EncryptionContext:SecretARN": {
                        "Ref": "QueueSecret"
                      }
                    }
                  }
                },
                {
                  "Fn::If": [
                    "HasAsr",
                    {
                      "Effect": "Allow",
                      "Action": "kms:Decrypt",
                      "Resource": {
                        "Ref": "AsrQueueKeyArn"
                      },
                      "Condition": {
                        "StringEquals": {
                          "kms:ViaService": {
                            "Fn::Sub": "secretsmanager.${AWS::Region}.${AWS::URLSuffix}"
                          },
                          "kms:EncryptionContext:SecretARN": {
                            "Ref": "AsrQueueSecretArn"
                          }
                        }
                      }
                    },
                    {
                      "Ref": "AWS::NoValue"
                    }
                  ]
                }
              ]
            }
          }
        ],
        "Tags": [
          {
            "Key": "Application",
            "Value": "PlatinumCircles"
          },
          {
            "Key": "Purpose",
            "Value": "LiveTaskLauncher"
          }
        ]
      }
    },
    "Launcher": {
      "Type": "AWS::Lambda::Function",
      "Properties": {
        "Runtime": "python3.13",
        "Handler": "index.handler",
        "Architectures": [
          "arm64"
        ],
        "MemorySize": 256,
        "Timeout": 45,
        "ReservedConcurrentExecutions": 1,
        "Role": {
          "Fn::GetAtt": [
            "LauncherRole",
            "Arn"
          ]
        },
        "Code": {
          "ZipFile": "\"\"\"Bounded ECS queue launcher. No broker, provider, media, or user credentials.\n\nOne durable reservation precedes every RunTask. Lost responses reuse the exact\nrequest/clientToken. Uncertain reservations are never refunded or discarded.\n\"\"\"\nimport datetime\nimport json\nimport os\nimport re\nimport time\nimport urllib.request\nimport uuid\n\nDAY_BUDGET = 7200  # seconds of a 2-vCPU/4-GiB task; ASR uses half this rate.\n\n\ndef configuration(env):\n    region = env.get(\"AWS_REGION\", \"\")\n    account = env.get(\"AWS_ACCOUNT_ID\", \"\")\n    project = env.get(\"SUPABASE_PROJECT_REF\", \"\")\n    if region != \"us-east-2\" or not re.fullmatch(r\"\\d{12}\", account) or not re.fullmatch(r\"[a-z0-9]{20}\", project):\n        raise ValueError(\"launcher_configuration_invalid\")\n    prefix = f\"arn:aws:ecs:{region}:{account}:\"\n    lanes = []\n    for name, upper, container, seconds, charge, endpoint, deadline_name in [\n        (\"renderer\", \"RENDERER\", \"renderer\", 600, 720, \"live-clip-scaler\", \"LIVE_CLIP_TASK_DEADLINE_MS\"),\n        (\"transcription\", \"ASR\", \"transcription\", 240, 180, \"live-transcription-worker\", \"LIVE_TRANSCRIPTION_TASK_DEADLINE_MS\"),\n    ]:\n        if name == \"transcription\" and env.get(\"ASR_ENABLED\") != \"true\":\n            continue\n        cluster = env.get(upper + \"_CLUSTER_ARN\", \"\")\n        definition = env.get(upper + \"_TASK_ARN\", \"\")\n        secret = env.get(upper + \"_QUEUE_SECRET_ARN\", \"\")\n        group = env.get(upper + \"_SECURITY_GROUP\", \"\")\n        subnets = env.get(upper + \"_SUBNET_IDS\", \"\").split(\",\")\n        if not re.fullmatch(re.escape(prefix) + r\"cluster/[A-Za-z0-9_-]{1,255}\", cluster):\n            raise ValueError(\"launcher_configuration_invalid\")\n        if not re.fullmatch(re.escape(prefix) + r\"task-definition/[A-Za-z0-9_-]{1,255}:[1-9][0-9]*\", definition):\n            raise ValueError(\"launcher_configuration_invalid\")\n        if not re.fullmatch(f\"arn:aws:secretsmanager:{region}:{account}:secret:[A-Za-z0-9/_+=.@-]+\", secret):\n            raise ValueError(\"launcher_configuration_invalid\")\n        if not re.fullmatch(r\"sg-[0-9a-f]{8,17}\", group) or len(subnets) not in (1, 2, 3) or any(not re.fullmatch(r\"subnet-[0-9a-f]{8,17}\", item) for item in subnets):\n            raise ValueError(\"launcher_configuration_invalid\")\n        lanes.append(dict(name=name, container=container, seconds=seconds, charge=charge,\n                          window=720 if name == \"renderer\" else 360, cluster=cluster,\n                          definition=definition, secret=secret, group=group, subnets=subnets,\n                          endpoint=f\"https://{project}.supabase.co/functions/v1/{endpoint}\",\n                          deadline_name=deadline_name))\n    return dict(lanes=lanes, enabled=env.get(\"LAUNCH_ENABLED\") == \"true\", account=account, region=region)\n\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        return None\n\n\ndef peek(lane, secrets):\n    value = secrets.get_secret_value(SecretId=lane[\"secret\"]).get(\"SecretString\", \"\")\n    if not isinstance(value, str) or not re.fullmatch(r\"[A-Za-z0-9_+=./-]{32,256}\", value):\n        raise ValueError(\"queue_credential_invalid\")\n    request = urllib.request.Request(lane[\"endpoint\"], data=b'{\"action\":\"peek\"}', method=\"POST\",\n                                     headers={\"Authorization\": \"Bearer \" + value, \"Content-Type\": \"application/json\", \"Accept\": \"application/json\"})\n    with urllib.request.build_opener(NoRedirect).open(request, timeout=4) as response:\n        body = response.read(2049)\n        if response.status != 200 or len(body) > 2048:\n            raise ValueError(\"queue_unavailable\")\n    data = json.loads(body)\n    if not isinstance(data, dict) or set(data) != {\"enabled\", \"due\", \"active\"} or type(data[\"enabled\"]) is not bool or type(data[\"due\"]) is not bool or type(data[\"active\"]) is not int or not 0 <= data[\"active\"] <= 2:\n        raise ValueError(\"queue_response_invalid\")\n    return data\n\n\nclass Ledger:\n    def __init__(self, client, table):\n        self.client, self.table = client, table\n\n    def slot(self):\n        item = self.client.get_item(TableName=self.table, Key={\"id\": {\"S\": \"slot\"}}, ConsistentRead=True).get(\"Item\")\n        if not item:\n            return None\n        return json.loads(item[\"value\"][\"S\"])\n\n    def reserve(self, reservation):\n        # Transaction serialization enforces both the shared slot and daily cap.\n        day = reservation[\"day\"]\n        expiry = int(datetime.datetime.strptime(day, \"%Y-%m-%d\").replace(tzinfo=datetime.timezone.utc).timestamp()) + 90 * 86400\n        try:\n            self.client.transact_write_items(ClientRequestToken=reservation[\"token\"], TransactItems=[\n                {\"Put\": {\"TableName\": self.table, \"Item\": {\"id\": {\"S\": \"slot\"}, \"state\": {\"S\": \"active\"}, \"token\": {\"S\": reservation[\"token\"]}, \"value\": {\"S\": json.dumps(reservation, separators=(\",\", \":\"))}},\n                         \"ConditionExpression\": \"attribute_not_exists(#state) OR #state = :idle\", \"ExpressionAttributeNames\": {\"#state\": \"state\"}, \"ExpressionAttributeValues\": {\":idle\": {\"S\": \"idle\"}}}},\n                {\"Update\": {\"TableName\": self.table, \"Key\": {\"id\": {\"S\": \"day#\" + day}},\n                            \"UpdateExpression\": \"SET expires_at = :expires ADD used_seconds :charge, launches :one\",\n                            \"ConditionExpression\": \"attribute_not_exists(used_seconds) OR used_seconds <= :maximum\",\n                            \"ExpressionAttributeValues\": {\":expires\": {\"N\": str(expiry)}, \":charge\": {\"N\": str(reservation[\"charge\"])}, \":one\": {\"N\": \"1\"}, \":maximum\": {\"N\": str(DAY_BUDGET - reservation